package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/Livepeer-FrameWorks/monorepo/pkg/events"
)

// The SDK version is the npm package version; changesets bump it and emit
// copies it into the Go and Python packages.
const npmPackagePath = "npm_api/package.json"

// Generated files per language.
var emitTargets = map[string][]string{
	"ts": {"npm_api/src/generated/manifest.ts", "npm_api/src/generated/events.ts"},
	"go": {"sdk_go/manifest_gen.go", "sdk_go/events_gen.go"},
	"py": {"sdk_python/src/livepeer_frameworks/_generated/manifest.py", "sdk_python/src/livepeer_frameworks/_generated/events.py"},
}

type emitInput struct {
	Version   string
	Line      string
	MinServer string
	Ops       []manifestOperation
	Events    []publicEvent
}

// publicEvent is one registered public event type and the proto message
// that is its payload.
type publicEvent struct {
	Type      string
	Message   string // proto message name, e.g. ClipReady
	ProtoFile string // e.g. events/public/v1/media.proto
}

func publicEvents() []publicEvent {
	var out []publicEvent
	for _, spec := range events.Specs() {
		if !spec.Public() {
			continue
		}
		desc := spec.NewMessage().ProtoReflect().Descriptor()
		out = append(out, publicEvent{
			Type:      spec.Type,
			Message:   string(desc.Name()),
			ProtoFile: desc.ParentFile().Path(),
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Type < out[j].Type })
	return out
}

func sdkVersion(repo string) (string, error) {
	data, err := os.ReadFile(filepath.Join(repo, npmPackagePath))
	if err != nil {
		return "", err
	}
	var pkg struct {
		Version string `json:"version"`
	}
	if err := json.Unmarshal(data, &pkg); err != nil {
		return "", fmt.Errorf("%s: %w", npmPackagePath, err)
	}
	if pkg.Version == "" {
		return "", fmt.Errorf("%s has no version", npmPackagePath)
	}
	return pkg.Version, nil
}

// render returns the generated files of one language keyed by repo path.
func (in emitInput) render(lang string) (map[string]string, error) {
	paths := emitTargets[lang]
	switch lang {
	case "ts":
		return map[string]string{paths[0]: in.tsManifest(), paths[1]: in.tsEvents()}, nil
	case "go":
		return map[string]string{paths[0]: in.goManifest(), paths[1]: in.goEvents()}, nil
	case "py":
		return map[string]string{paths[0]: in.pyManifest(), paths[1]: in.pyEvents()}, nil
	}
	return nil, fmt.Errorf("unknown language %q (want ts, go, or py)", lang)
}

const generatedNote = "Code generated by scripts/sdkcontract from pkg/graphql/public and the event registry. DO NOT EDIT."

func (in emitInput) tsManifest() string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\n", generatedNote)
	b.WriteString("export type OperationKind = \"query\" | \"mutation\" | \"subscription\";\n\n")
	b.WriteString("export interface OperationInfo {\n  readonly kind: OperationKind;\n  readonly since: string;\n  readonly hash: string;\n}\n\n")
	fmt.Fprintf(&b, "/** The SDK package version. */\nexport const sdkVersion = %q;\n\n", in.Version)
	fmt.Fprintf(&b, "/** The SDK compatibility line; under 0.x each minor version is its own line. */\nexport const sdkLine = %q;\n\n", in.Line)
	fmt.Fprintf(&b, "/** The oldest FrameWorks release this SDK line supports. */\nexport const minServerVersion = %q;\n\n", in.MinServer)
	b.WriteString("/** Every operation this SDK ships, with the first release that serves it. */\n")
	b.WriteString("export const operations = {\n")
	for _, op := range in.Ops {
		fmt.Fprintf(&b, "  %s: { kind: %q, since: %q, hash: %q },\n", op.Name, op.Kind, op.Since, op.Hash)
	}
	b.WriteString("} as const satisfies Record<string, OperationInfo>;\n\n")
	b.WriteString("export type OperationName = keyof typeof operations;\n")
	return b.String()
}

func (in emitInput) tsEvents() string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\n", generatedNote)
	byFile := map[string][]string{}
	for _, ev := range in.Events {
		byFile[ev.ProtoFile] = append(byFile[ev.ProtoFile], ev.Message)
	}
	files := make([]string, 0, len(byFile))
	for f := range byFile {
		files = append(files, f)
	}
	sort.Strings(files)
	for _, f := range files {
		msgs := byFile[f]
		sort.Strings(msgs)
		fmt.Fprintf(&b, "import { %s } from \"./proto/%s.js\";\n", strings.Join(msgs, ", "), strings.TrimSuffix(f, ".proto"))
	}
	b.WriteString("\n/** The payload type of each public event type. */\nexport interface PublicEventDataMap {\n")
	for _, ev := range in.Events {
		fmt.Fprintf(&b, "  %q: %s;\n", ev.Type, ev.Message)
	}
	b.WriteString("}\n\n")
	b.WriteString("export type PublicEventType = keyof PublicEventDataMap;\n\n")
	b.WriteString("/** Decoders for each public event type, keyed by the event type. */\n")
	b.WriteString("export const publicEventDecoders: {\n  readonly [K in PublicEventType]: { fromJSON(object: unknown): PublicEventDataMap[K] };\n} = {\n")
	for _, ev := range in.Events {
		fmt.Fprintf(&b, "  %q: %s,\n", ev.Type, ev.Message)
	}
	b.WriteString("};\n")
	return b.String()
}

func (in emitInput) goManifest() string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\npackage frameworks\n\n", generatedNote)
	fmt.Fprintf(&b, "// SDKVersion is the version of this SDK.\nconst SDKVersion = %q\n\n", in.Version)
	fmt.Fprintf(&b, "// SDKLine is the compatibility line of this SDK; under 0.x each minor version is its own line.\nconst SDKLine = %q\n\n", in.Line)
	fmt.Fprintf(&b, "// MinServerVersion is the oldest FrameWorks release this SDK line supports.\nconst MinServerVersion = %q\n\n", in.MinServer)
	b.WriteString("// operations lists every operation this SDK ships with the first release that serves it.\n")
	b.WriteString("var operations = map[string]operationInfo{\n")
	width := 0
	for _, op := range in.Ops {
		if l := len(op.Name) + 3; l > width {
			width = l
		}
	}
	for _, op := range in.Ops {
		key := fmt.Sprintf("%q:", op.Name)
		fmt.Fprintf(&b, "\t%-*s {Kind: %q, Since: %q},\n", width, key, op.Kind, op.Since)
	}
	b.WriteString("}\n")
	return b.String()
}

func (in emitInput) goEvents() string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\npackage frameworks\n\n", generatedNote)
	b.WriteString("import (\n\tpublicv1 \"github.com/Livepeer-FrameWorks/monorepo/pkg/proto/events/public/v1\"\n\t\"google.golang.org/protobuf/proto\"\n)\n\n")
	b.WriteString("// publicEventMessages returns an empty payload message for each public event type.\n")
	b.WriteString("var publicEventMessages = map[string]func() proto.Message{\n")
	width := 0
	for _, ev := range in.Events {
		if l := len(ev.Type) + 3; l > width {
			width = l
		}
	}
	for _, ev := range in.Events {
		key := fmt.Sprintf("%q:", ev.Type)
		fmt.Fprintf(&b, "\t%-*s func() proto.Message { return &publicv1.%s{} },\n", width, key, ev.Message)
	}
	b.WriteString("}\n")
	return b.String()
}

func (in emitInput) pyManifest() string {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", generatedNote)
	b.WriteString("from typing import Final, Literal, TypedDict\n\n\n")
	b.WriteString("class OperationInfo(TypedDict):\n    kind: Literal[\"query\", \"mutation\", \"subscription\"]\n    since: str\n\n\n")
	fmt.Fprintf(&b, "SDK_VERSION: Final = %q\n", in.Version)
	fmt.Fprintf(&b, "SDK_LINE: Final = %q\n", in.Line)
	fmt.Fprintf(&b, "MIN_SERVER_VERSION: Final = %q\n\n", in.MinServer)
	b.WriteString("OPERATIONS: Final[dict[str, OperationInfo]] = {\n")
	for _, op := range in.Ops {
		fmt.Fprintf(&b, "    %q: {\"kind\": %q, \"since\": %q},\n", op.Name, op.Kind, op.Since)
	}
	b.WriteString("}\n")
	return b.String()
}

func (in emitInput) pyEvents() string {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", generatedNote)
	msgs := make([]string, 0, len(in.Events))
	for _, ev := range in.Events {
		msgs = append(msgs, ev.Message)
	}
	sort.Strings(msgs)
	b.WriteString("from typing import Final\n\nimport betterproto2\n\n")
	b.WriteString("from .proto.frameworks.events.public.v1 import (\n")
	for _, m := range msgs {
		fmt.Fprintf(&b, "    %s,\n", m)
	}
	b.WriteString(")\n\n")
	b.WriteString("PUBLIC_EVENT_MESSAGES: Final[dict[str, type[betterproto2.Message]]] = {\n")
	for _, ev := range in.Events {
		fmt.Fprintf(&b, "    %q: %s,\n", ev.Type, ev.Message)
	}
	b.WriteString("}\n")
	return b.String()
}

// writeOrCheck writes files, or with check reports the ones that differ.
func writeOrCheck(repo string, files map[string]string, check bool) ([]string, error) {
	var stale []string
	paths := make([]string, 0, len(files))
	for p := range files {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		full := filepath.Join(repo, p)
		current, err := os.ReadFile(full)
		if err == nil && bytes.Equal(current, []byte(files[p])) {
			continue
		}
		if check {
			stale = append(stale, p)
			continue
		}
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return nil, err
		}
		if err := os.WriteFile(full, []byte(files[p]), 0o644); err != nil {
			return nil, err
		}
	}
	return stale, nil
}
